#!/usr/bin/env python3
"""
scan.py — اسکن مکانیکی متن فارسی برای یافتن ایرادهای رایج بر پایه‌ی کتاب
«راهنمای ویراستاری و درست‌نویسی» (حسن ذوالفقاری).

خروجی فقط «سرنخ» است، نه حکم. هر یافته را خودت در بافت جمله داوری کن.

کاربرد:
    python3 scan.py input.txt            # گزارش خوانا (Markdown)
    python3 scan.py input.docx --json    # خروجی JSON
    cat text | python3 scan.py -         # از stdin

ورودی: .txt / .md / .docx (برای docx، python-docx لازم است).
"""
import sys, re, json, argparse
from collections import Counter

ZW = "‌"
FA = "آ-یء-يپچژکگی"   # حروف فارسی/عربی
W = f"[{FA}{ZW}]"                                             # نویسه‌ی واژه
B = f"(?<![{FA}{ZW}])"                                        # مرز آغاز واژه
E = f"(?![{FA}{ZW}])"                                         # مرز پایان واژه


def words(*ws):
    return B + "(?:" + "|".join(ws) + ")" + E


