SENT_SPLIT = re.compile(r"(?<=[.؟!?])\s+|\n+")


def load_text(path):
    if path == "-":
        return sys.stdin.read()
    if path.lower().endswith(".docx"):
        try:
            import docx  # python-docx
        except ImportError:
            sys.exit("python-docx نصب نیست: pip install python-docx --break-system-packages")
        d = docx.Document(path)
        parts = [p.text for p in d.paragraphs]
        for t in d.tables:
            for row in t.rows:
                for c in row.cells:
                    parts.append(c.text)
        return "\n".join(parts)
    with open(path, encoding="utf-8") as f:
        return f.read()


def scan(text):
    findings = []
    lines = text.split("\n")
    for ln, line in enumerate(lines, 1):
        for rid, sev, kind, pat, hint, ref in RULES:
            for m in re.finditer(pat, line):
                s, e = m.start(), m.end()
                ctx = line[max(0, s - 25):min(len(line), e + 25)]
                findings.append({"line": ln, "col": s + 1, "rule": rid, "severity": sev,
                                 "type": kind, "match": m.group(0), "context": ctx,
                                 "hint": hint, "ref": ref})
    # جمله‌های بلند
    for ln, line in enumerate(lines, 1):
        for sent in SENT_SPLIT.split(line):
            n = len(re.findall(rf"{W}+", sent))
            if n > 40:
                findings.append({"line": ln, "col": 1, "rule": "long-sentence", "severity": "بررسی",
                                 "type": "زبانی", "match": f"{n} واژه",
                                 "context": sent[:80] + "…", "hint": "جمله‌ی بلند؛ شکستن به چند جمله‌ی کوتاه یا حذف معترضه‌ها", "ref": "ص ۲۱۶–۲۲۲"})
    # یکدستی «ه‌ی» و «ۀ»
    a = len(re.findall(rf"ه{ZW}ی{E}", text)); b = text.count("ۀ")
    if a and b:
        findings.append({"line": 0, "col": 0, "rule": "consistency-izafe", "severity": "بررسی", "type": "فنی",
                         "match": f"ه‌ی×{a} / ۀ×{b}", "context": "", "hint": "دو شیوه‌ی نشانه‌ی اضافه پس از «ه»؛ یکدست کن", "ref": "ص ۶۷"})
    return findings


def to_md(findings):
    if not findings:
        return "هیچ الگوی مکانیکی‌ای یافت نشد (این به معنای بی‌غلط بودن متن نیست)."
    cnt = Counter((f["type"], f["rule"]) for f in findings)
    out = ["## خلاصه‌ی اسکن", "", "| نوع | قاعده | تعداد |", "|---|---|---|"]
    for (t, r), c in cnt.most_common():
        out.append(f"| {t} | {r} | {c} |")
    out += ["", "## یافته‌ها", "", "| سطر | شدت | نوع | یافته | بافت | راهنما | مرجع |", "|---|---|---|---|---|---|---|"]
    for f in findings:
        ctx = f["context"].replace("|", "¦")
        out.append(f"| {f['line']} | {f['severity']} | {f['type']} | {f['match']} | {ctx} | {f['hint']} | {f['ref']} |")
    return "\n".join(out)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("path")
    ap.add_argument("--json", action="store_true")
    a = ap.parse_args()
    fs = scan(load_text(a.path))
    print(json.dumps(fs, ensure_ascii=False, indent=1) if a.json else to_md(fs))
